// Feature knowledge base (qa/kb): parsing, source references, checks, coverage, search.
//
// Layout:  <kb>/index.md                     feature map (one table)
//          <kb>/<feature>/overview.md        what the feature does, rules and flows, with sources
//          <kb>/<feature>/decisions.md       answered questions (intent only), who and when
//          <kb>/<feature>/known-issues.md    open and fixed bugs
//          <kb>/<feature>/coverage.md        generated by `kb.mjs coverage`, never written by the model
//
// Every fact cites its source as [src: kind:path#anchor], several separated by ";".
//   atlas:<page>#M12   ticket:<path>#AC4   case:<cases file>#TC-REG-010   bug:<path>
//   manual:<path>#<heading or L12-14>   import:<path>#row 7
// Decisions pin the atlas facts they cite with a hash (atlas:page#R6 @1a2b3c4d, added by
// `kb.mjs stamp`); when the atlas fact changes, the decision is reported as stale.
import { existsSync, readFileSync, readdirSync, statSync, realpathSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { join, resolve, relative, sep } from 'node:path';
import { looksSecret } from './kit.mjs';
import { csvRecords, mapColumns } from './csv.mjs';
import { parseCases } from '../check-cases.mjs';

export const FEATURE_FILES = ['overview.md', 'decisions.md', 'known-issues.md'];
export const DEFAULT_LOAD = ['decisions.md', 'known-issues.md'];
// similar = an atlas page of ANOTHER, already built feature that a pre-UI case borrows text from.
export const KINDS = ['atlas', 'ticket', 'case', 'bug', 'manual', 'import', 'similar'];
const SLUG = /^[a-z0-9]+(-[a-z0-9]+)*$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;
const EMAIL = /\b[A-Za-z0-9._%+-]+@([A-Za-z0-9-]+\.)+[A-Za-z]{2,}\b/g;

export const norm = (s) => s.replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/\s+/g, ' ').trim();
export const factHash = (text) => createHash('sha256').update(norm(text)).digest('hex').slice(0, 8);
export const tokens = (text) => Math.ceil(text.length / 4); // rough estimate, same for every check

export function kbContext(projectDir, config = {}) {
  const project = resolve(projectDir);
  const out = config.output ?? {};
  return {
    project,
    root: join(project, out.kb ?? 'qa/kb'),
    atlasDir: join(project, out.atlas ?? 'qa/atlas'),
    casesDir: join(project, out.cases ?? 'qa/cases'),
    sourcesDir: join(project, out.sources ?? 'qa/sources'),
    reportsDir: join(project, out.reports ?? 'qa/reports'),
    bugs: out.bugs ?? 'qa/bugs',
    cap: config.kb?.token_cap ?? 4000,
    testDomain: config.app?.test_data?.email_domain ?? 'example.test',
  };
}

const read = (f) => readFileSync(f, 'utf8').replace(/\r\n?/g, '\n');
// Paths in messages always use forward slashes, on every OS.
const relp = (from, to) => relative(from, to).split(sep).join('/');
const within = (base, f) => { const r = relative(base, f); return !!r && !r.startsWith('..') && !r.startsWith(sep) && !/^[A-Za-z]:/.test(r); };
// Inside the project, also after following symbolic links (a link in the project may point outside).
export const inside = (base, f) => {
  if (!within(base, f)) return false;
  try { return !existsSync(f) || within(realpathSync(base), realpathSync(f)); } catch { return false; }
};
export const isSlug = (s) => SLUG.test(String(s ?? ''));

// ---- index ----------------------------------------------------------------------

const list = (cell) => cell.split(',').map((x) => x.trim()).filter((x) => x && x !== '—' && x !== '-');

export function parseIndex(text) {
  const rows = [];
  const problems = [];
  let header = null;
  text.split('\n').forEach((line, i) => {
    if (!/^\s*\|/.test(line)) return;
    const cells = line.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim());
    if (!header) { header = cells.map((c) => c.toLowerCase()); return; }
    if (cells.every((c) => /^:?-+:?$/.test(c))) return;
    const get = (name) => cells[header.indexOf(name)] ?? '';
    rows.push({ line: i + 1, feature: get('feature'), folder: get('folder'), atlas: list(get('atlas pages')),
      cases: list(get('cases')), tickets: list(get('tickets')), updated: get('updated') });
  });
  if (!header) problems.push({ line: null, message: 'index.md has no feature table' });
  else for (const need of ['feature', 'folder', 'atlas pages', 'cases', 'tickets', 'updated']) {
    if (!header.includes(need)) problems.push({ line: null, message: `index.md table is missing the "${need}" column` });
  }
  return { rows, problems };
}

// ---- source references ---------------------------------------------------------------

const SRC = /\[src:\s*([^\]]*)\]/g;

export function parseRefs(line) {
  const refs = [];
  for (const m of line.matchAll(SRC)) {
    for (const part of m[1].split(';').map((x) => x.trim()).filter(Boolean)) {
      const r = part.match(/^([a-z]+):\s*([^#@]+?)\s*(?:#\s*([^@]+?))?\s*(?:@([0-9a-f]{8}))?$/);
      refs.push(r ? { raw: part, kind: r[1], path: r[2], anchor: r[3] ?? null, hash: r[4] ?? null } : { raw: part, bad: true });
    }
  }
  return refs;
}

// Quoted text on a line, outside [src: …]: "…", “…” and «…» (at least 3 characters).
export function quotes(line) {
  const body = line.replace(SRC, ' ');
  const out = [];
  for (const m of body.matchAll(/"([^"\n]{3,}?)"|“([^”\n]{3,}?)”|«([^»\n]{3,}?)»/g)) out.push({ text: m[1] ?? m[2] ?? m[3], ui: m[3] !== undefined });
  return out;
}

function refFile(ref, ctx) {
  if (ref.kind === 'atlas' || ref.kind === 'similar') return join(ctx.atlasDir, ref.path.endsWith('.md') ? ref.path : `${ref.path}.md`);
  if (ref.kind === 'case' && !/[\\/]/.test(ref.path)) return join(ctx.casesDir, ref.path);
  return join(ctx.project, ref.path);
}

// Quoted strings in free text (imported cases and manuals): "…", “…”, «…» and '…' when it holds
// at least two words (single quotes are also apostrophes).
export function looseQuotes(text) {
  const out = new Set(quotes(text.replace(/\n/g, ' ')).map((q) => q.text));
  for (const m of text.matchAll(/(?:^|[\s(])'([^'\n]{3,}?)'(?=[\s.,;:)!?]|$)/g)) if (/\s/.test(m[1].trim())) out.add(m[1]);
  return [...out].map((x) => x.trim()).filter((x) => x.length >= 3);
}

// Atlas text that was observed (open questions and notes ground nothing).
export const observedAtlas = (text) => text.split(/^(?=#{1,6}\s)/m).filter((s) => !/^#{1,6}\s*(Open questions|Notes)\b/i.test(s)).join('');
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function section(lines, i) {
  const level = lines[i].match(/^(#+)/)[1].length;
  let j = i + 1;
  while (j < lines.length && !(lines[j].match(/^(#+)\s/) && lines[j].match(/^(#+)/)[1].length <= level)) j++;
  return lines.slice(i, j).join('\n');
}

// Returns { text } for the anchored part of the source, or { problem }.
export function resolveRef(ref, ctx) {
  if (ref.bad) return { problem: `"${ref.raw}" is not a source reference (use kind:path#anchor)` };
  if (!KINDS.includes(ref.kind)) return { problem: `unknown source kind "${ref.kind}" (use ${KINDS.join(', ')})` };
  const file = refFile(ref, ctx);
  if (!inside(ctx.project, file)) return { problem: `${ref.raw}: the source must be inside the project` };
  // A source is never something ReconQA (or the model) wrote itself, and each kind has its folder.
  const own = [ctx.root, ctx.reportsDir, join(ctx.project, '.reconqa')].filter(Boolean);
  if (ref.kind !== 'case' && own.some((d) => inside(d, file))) return { problem: `${ref.raw}: the knowledge base, reports and .reconqa are not sources` };
  const pinned = { atlas: ctx.atlasDir, similar: ctx.atlasDir, manual: ctx.sourcesDir, import: ctx.sourcesDir, bug: join(ctx.project, ctx.bugs ?? 'qa/bugs') };
  if (pinned[ref.kind] && !inside(pinned[ref.kind], file)) return { problem: `${ref.raw}: ${ref.kind} sources must be in ${relp(ctx.project, pinned[ref.kind])}` };
  if (ref.kind === 'case' && !inside(ctx.casesDir, file) && !inside(ctx.sourcesDir, file)) return { problem: `${ref.raw}: case sources must be in ${relp(ctx.project, ctx.casesDir)} or ${relp(ctx.project, ctx.sourcesDir)}` };
  if (ref.kind === 'ticket' && [ctx.casesDir, ctx.atlasDir].some((d) => inside(d, file))) return { problem: `${ref.raw}: a ticket source can't be a cases or atlas file` };
  if (!existsSync(file) || !statSync(file).isFile()) return { problem: `${ref.raw}: file not found (${relp(ctx.project, file)})` };
  let text = read(file);
  if (ref.kind === 'atlas' || ref.kind === 'similar') text = observedAtlas(text);
  if (!ref.anchor) return { text, file };
  const a = ref.anchor;
  const lines = text.split('\n');

  if ((ref.kind === 'atlas' || ref.kind === 'similar') && /^[MR]\d+$/.test(a)) {
    const re = a[0] === 'M' ? new RegExp(`^\\|\\s*${a}\\s*\\|`) : new RegExp(`^\\s*[-*]\\s*${a}\\b`);
    const hit = lines.find((l) => re.test(l));
    return hit ? { text: hit, file } : { problem: `${ref.raw}: ${a} not found in the atlas page` };
  }
  const range = a.match(/^L(\d+)(?:-(\d+))?$/);
  if (range) {
    const from = Number(range[1]), to = Number(range[2] ?? range[1]);
    if (from < 1 || to < from || to > lines.length) return { problem: `${ref.raw}: lines ${a} are outside the file (${lines.length} lines)` };
    return { text: lines.slice(from - 1, to).join('\n'), file };
  }
  if (file.endsWith('.csv')) {
    const { header, records } = csvRecords(text);
    const row = a.match(/^row\s*(\d+)$/i);
    if (row) {
      const r = records[Number(row[1]) - 1];
      return r ? { text: Object.values(r.values).join(' | '), file } : { problem: `${ref.raw}: the file has ${records.length} data rows` };
    }
    const idCol = mapColumns(header).id;
    if (idCol) {
      const at = records.findIndex((r) => r.values[idCol] === a);
      if (at >= 0) {
        let end = at + 1;
        while (end < records.length && records[end].values[idCol] === '') end++;
        return { text: records.slice(at, end).map((r) => Object.values(r.values).join(' | ')).join('\n'), file };
      }
    }
  }
  // AC4 = item 4 of a numbered list under an "Acceptance criteria" heading (when the ticket doesn't write "AC4" itself).
  const ac = a.match(/^AC\s*(\d+)$/i);
  if (ac && !lines.some((l) => new RegExp(`\\b${esc(a)}\\b`).test(l))) {
    const start = lines.findIndex((l) => /^#{1,6}\s*Acceptance criteria\b/i.test(l));
    if (start >= 0) {
      const item = section(lines, start).split('\n').find((l) => new RegExp(`^\\s*${ac[1]}[.)]\\s`).test(l));
      if (item) return { text: item, file };
    }
    return { problem: `${ref.raw}: acceptance criterion ${ac[1]} not found` };
  }
  const h = lines.findIndex((l) => /^#{1,6}\s/.test(l) && l.toLowerCase().includes(a.toLowerCase()));
  if (h >= 0) return { text: section(lines, h), file };
  const re = new RegExp(`(^|[^A-Za-z0-9])${esc(a)}([^A-Za-z0-9]|$)`);
  const hits = lines.filter((l) => re.test(l));
  return hits.length ? { text: hits.join('\n'), file } : { problem: `${ref.raw}: "${a}" not found in ${relp(ctx.project, file)}` };
}

// ---- entries (decisions, known issues) -----------------------------------------------

export function entries(text) {
  const lines = text.split('\n');
  const out = [];
  let cur = null;
  lines.forEach((line, i) => {
    const h = line.match(/^##\s+([A-Z]+\d+)\b\s*(.*)$/);
    if (h) { cur = { id: h[1], title: h[2].trim(), line: i + 1, fields: {}, lines: [] }; out.push(cur); return; }
    if (/^##\s/.test(line)) { cur = null; return; }
    if (!cur) return;
    cur.lines.push({ text: line, line: i + 1 });
    const f = line.match(/^\s*-\s*([A-Za-z ]+):\s*(.*)$/);
    if (f) cur.fields[f[1].trim().toLowerCase()] = { value: f[2].trim(), line: i + 1 };
  });
  return out;
}

// ---- check ------------------------------------------------------------------------

function contentLines(text) {
  const out = [];
  let fence = false, comment = false;
  text.split('\n').forEach((line, i) => {
    if (/^\s*```/.test(line)) { fence = !fence; return; }
    if (fence) return;
    if (comment) { if (line.includes('-->')) comment = false; return; }
    if (/^\s*<!--/.test(line)) { if (!line.includes('-->')) comment = true; return; }
    out.push({ text: line, line: i + 1 });
  });
  return out;
}

function sensitiveLine(line, testDomain) {
  if (looksSecret(line)) return 'looks like a secret (token, key or password in a URL)';
  for (const m of line.matchAll(EMAIL)) {
    const d = m[0].split('@')[1].toLowerCase();
    if (d !== testDomain && !d.endsWith(`.${testDomain}`) && !/(^|\.)users\.noreply\.github\.com$/.test(d)) return `has an email address that is not test data (${m[0].replace(/^(.).*@/, '$1…@')})`;
  }
  return null;
}

// Checks one KB file's lines: sources resolve, quotes appear in a cited source, no secrets.
function checkFactLines(file, text, ctx, add, { requireSrcUnder = [] } = {}) {
  let heading = '';
  for (const { text: line, line: n } of contentLines(text)) {
    const h = line.match(/^#{1,6}\s+(.*)$/);
    if (h) { heading = h[1].trim().toLowerCase(); continue; }
    const leak = sensitiveLine(line, ctx.testDomain);
    if (leak) add('error', file, n, `this line ${leak}`);
    const refs = parseRefs(line);
    const qs = quotes(line);
    const isFact = /^\s*([-*]|\d+\.)\s+\S/.test(line);
    if (!refs.length) {
      if (qs.length) add('error', file, n, 'quoted text needs a source: add [src: kind:path#anchor]');
      else if (isFact && requireSrcUnder.some((s) => heading.startsWith(s))) add('error', file, n, `every item under "${heading}" needs a source: add [src: kind:path#anchor]`);
      continue;
    }
    const texts = [];
    for (const r of refs) {
      const got = resolveRef(r, ctx);
      if (got.problem) add('error', file, n, got.problem);
      else texts.push(norm(got.text));
    }
    if (!texts.length) continue;
    for (const q of qs) {
      if (!texts.some((t) => t.includes(norm(q.text)))) add('error', file, n, `"${q.text}" is not found word for word in the cited source${refs.length > 1 ? 's' : ''}`);
    }
  }
}

export function checkKb(ctx) {
  const problems = [];
  const add = (level, file, line, message) => problems.push({ level, file: file ? relative(ctx.project, file) : null, line, message });
  const indexFile = join(ctx.root, 'index.md');
  if (!existsSync(ctx.root)) return { problems: [], features: [], missing: true };
  if (!existsSync(indexFile)) { add('error', ctx.root, null, 'no index.md (run: kb.mjs init)'); return { problems, features: [] }; }

  const { rows, problems: ip } = parseIndex(read(indexFile));
  for (const p of ip) add('error', indexFile, p.line, p.message);
  const seen = new Set();
  for (const r of rows) {
    if (!SLUG.test(r.folder)) add('error', indexFile, r.line, `folder "${r.folder}" must be lowercase words with dashes`);
    if (seen.has(r.folder)) add('error', indexFile, r.line, `folder "${r.folder}" is listed twice`);
    seen.add(r.folder);
    if (!r.feature) add('error', indexFile, r.line, 'feature name is empty');
    if (r.updated && !DATE.test(r.updated)) add('error', indexFile, r.line, `updated "${r.updated}" must be a date like 2026-11-26`);
    for (const p of r.atlas) if (!existsSync(join(ctx.atlasDir, p.endsWith('.md') ? p : `${p}.md`))) add('error', indexFile, r.line, `atlas page "${p}" not found in ${relp(ctx.project, ctx.atlasDir)}`);
    for (const c of r.cases) if (!existsSync(/[\\/]/.test(c) ? join(ctx.project, c) : join(ctx.casesDir, c))) add('error', indexFile, r.line, `cases file "${c}" not found`);
    for (const t of r.tickets) if (!existsSync(join(ctx.project, t))) add('error', indexFile, r.line, `ticket "${t}" not found`);
    const dir = join(ctx.root, r.folder);
    if (!existsSync(dir)) { add('error', indexFile, r.line, `folder ${r.folder}/ does not exist (run: kb.mjs new-feature ${r.folder} "${r.feature}")`); continue; }
    for (const f of FEATURE_FILES) if (!existsSync(join(dir, f))) add('error', join(dir, f), null, 'missing (copy it from the plugin templates/kb)');
  }
  for (const d of readdirSync(ctx.root)) {
    if (statSync(join(ctx.root, d)).isDirectory() && !seen.has(d)) add('error', join(ctx.root, d), null, `folder is not in index.md; add a row for it or remove it`);
  }
  checkFactLines(indexFile, read(indexFile), ctx, add);

  for (const r of rows) {
    const dir = join(ctx.root, r.folder);
    if (!existsSync(dir)) continue;
    const ov = join(dir, 'overview.md');
    if (existsSync(ov)) checkFactLines(ov, read(ov), ctx, add, { requireSrcUnder: ['rules', 'flows', 'from the manual'] });

    const dec = join(dir, 'decisions.md');
    if (existsSync(dec)) {
      const text = read(dec);
      checkFactLines(dec, text, ctx, add);
      for (const e of entries(text)) {
        if (!/^D\d+$/.test(e.id)) add('error', dec, e.line, `decision IDs are D1, D2, … ("${e.id}")`);
        for (const f of ['question', 'decision', 'who', 'date']) if (!e.fields[f]?.value) add('error', dec, e.line, `${e.id} needs a "- ${f[0].toUpperCase() + f.slice(1)}:" line`);
        if (e.fields.date?.value && !DATE.test(e.fields.date.value)) add('error', dec, e.fields.date.line, `${e.id}: date must look like 2026-11-26`);
        const d = e.fields.decision;
        if (d && /«[^»]+»|"[^"]{2,}"|“[^”]{2,}”/.test(d.value)) add('error', dec, d.line, `${e.id}: decisions settle intent, not UI text. Exact UI text comes only from the atlas; remove the quoted text`);
        const refs = e.lines.flatMap((l) => parseRefs(l.text).map((x) => ({ ...x, line: l.line })));
        if (!refs.length) add('error', dec, e.line, `${e.id} needs at least one [src: …] (the mismatch or ticket it answers)`);
        const status = (e.fields.status?.value ?? 'active').toLowerCase();
        if (!['active', 'stale', 'replaced'].includes(status)) add('error', dec, e.fields.status.line, `${e.id}: status must be active, stale or replaced`);
        for (const x of refs.filter((y) => y.kind === 'atlas')) {
          if (!x.anchor) { add('error', dec, x.line, `${e.id}: cite the atlas fact by its ID (atlas:page#M12 or #R6) or screen heading so changes can be noticed`); continue; }
          const got = resolveRef(x, ctx);
          if (got.problem) continue; // reported above
          if (!x.hash) add('error', dec, x.line, `${e.id}: ${x.raw} has no fingerprint (run: kb.mjs stamp ${r.folder})`);
          else if (x.hash !== factHash(got.text) && status === 'active') add('warn', dec, x.line, `${e.id} is STALE: the atlas fact ${x.kind}:${x.path}#${x.anchor} changed since the decision. Ask the team again, then set "- Status: stale" or update it`);
        }
      }
    }

    const ki = join(dir, 'known-issues.md');
    if (existsSync(ki)) {
      const text = read(ki);
      checkFactLines(ki, text, ctx, add);
      for (const e of entries(text)) {
        if (!/^K\d+$/.test(e.id)) add('error', ki, e.line, `known issue IDs are K1, K2, … ("${e.id}")`);
        const status = (e.fields.status?.value ?? '').toLowerCase();
        if (!['open', 'fixed', 'wont-fix'].includes(status)) add('error', ki, e.line, `${e.id} needs "- Status: open", "fixed" or "wont-fix"`);
        const hasSrc = e.lines.some((l) => parseRefs(l.text).length);
        if (!hasSrc && !e.fields.link?.value) add('error', ki, e.line, `${e.id} needs a bug file [src: bug:…] or a "- Link:" to the tracker`);
      }
    }

    const load = DEFAULT_LOAD.map((f) => join(dir, f)).filter(existsSync).map(read).join('\n');
    if (tokens(load) > ctx.cap) add('error', dir, null, `decisions.md + known-issues.md are about ${tokens(load)} tokens, over the cap of ${ctx.cap} (kb.token_cap). Move replaced decisions and fixed issues to an archive.md`);
    for (const f of ['overview.md']) {
      const p = join(dir, f);
      if (existsSync(p) && tokens(read(p)) > ctx.cap) add('error', p, null, `about ${tokens(read(p))} tokens, over the cap of ${ctx.cap}; split the feature`);
    }

    const cov = join(dir, 'coverage.md');
    if (r.cases.length || existsSync(cov)) {
      const want = coverage(r, ctx);
      if (!existsSync(cov)) add('error', cov, null, `missing (run: kb.mjs coverage ${r.folder})`);
      else if (read(cov) !== want) add('error', cov, null, `out of date or edited by hand (run: kb.mjs coverage ${r.folder})`);
    }
  }
  return { problems, features: rows };
}

// ---- coverage (generated) -----------------------------------------------------------

function atlasFacts(pages, ctx) {
  const messages = [], rules = [];
  for (const p of pages) {
    const f = join(ctx.atlasDir, p.endsWith('.md') ? p : `${p}.md`);
    if (!existsSync(f)) continue;
    for (const line of observedAtlas(read(f)).split('\n')) {
      const m = line.match(/^\|\s*(M\d+)\s*\|\s*([^|]+?)\s*\|\s*([^|]*?)\s*\|/);
      if (m) messages.push({ page: p, id: m[1], text: m[2], screen: m[3] });
      const r = line.match(/^\s*[-*]\s*(R\d+)\s+(.*)$/);
      if (r) rules.push({ page: p, id: r[1], text: r[2] });
    }
  }
  return { messages, rules };
}

function casesOf(files, ctx) {
  const out = [];
  for (const c of files) {
    const f = /[\\/]/.test(c) ? join(ctx.project, c) : join(ctx.casesDir, c);
    if (!existsSync(f)) continue;
    const text = read(f);
    if (f.endsWith('.csv')) {
      const { header, records } = csvRecords(text);
      const idCol = mapColumns(header).id ?? 'id';
      let cur = null;
      for (const r of records) {
        if (r.values[idCol]) { cur = { id: r.values[idCol], text: '' }; out.push(cur); }
        if (cur) cur.text += '\n' + Object.values(r.values).join('\n');
      }
      for (const k of out) if (k.quoted === undefined) k.quoted = looseQuotes(k.text).map(norm);
    } else {
      const lines = text.split('\n');
      for (const k of parseCases(text)) {
        const end = lines.findIndex((l, i) => i >= k.line && (/^###\s/.test(l) || /^#{1,6}\s*Mismatches\b/i.test(l)));
        out.push({ id: k.id, text: lines.slice(k.line - 1, end < 0 ? undefined : end).join('\n') });
      }
    }
  }
  return out;
}

const mentions = (text) => {
  const ids = new Set();
  for (const m of text.matchAll(/\b([MR])(\d+)(?:\s*[-–]\s*\1?(\d+))?\b/g)) {
    const from = Number(m[2]), to = Number(m[3] ?? m[2]);
    for (let k = from; k <= Math.min(to, from + 50); k++) ids.add(`${m[1]}${k}`);
  }
  return ids;
};

export function coverage(row, ctx) {
  const { messages, rules } = atlasFacts(row.atlas, ctx);
  const cases = casesOf(row.cases, ctx);
  // ReconQA cases mark UI text with «»; imported CSV cases use ordinary quotes.
  const ui = (c) => c.quoted ?? [...c.text.matchAll(/«([^»\n]+)»/g)].map((m) => norm(m[1]));
  // The same text on two screens (e.g. a required-field error on Login and on Registration) counts
  // for the screen the case names most often (all of them on a tie).
  const count = (hay, needle) => needle ? hay.toLowerCase().split(needle.toLowerCase()).length - 1 : 0;
  const textHit = (c, m) => {
    if (!ui(c).includes(norm(m.text))) return false;
    const same = messages.filter((x) => norm(x.text) === norm(m.text));
    if (same.length < 2) return true;
    const best = Math.max(...same.map((x) => count(c.text, x.screen)));
    return count(c.text, m.screen) === best;
  };
  const byMsg = new Map(messages.map((m) => [m.id, cases.filter((c) => mentions(c.text).has(m.id) || textHit(c, m)).map((c) => c.id)]));
  const byRule = new Map(rules.map((r) => {
    const named = [...mentions(r.text)].filter((x) => x.startsWith('M'));
    const ids = new Set(cases.filter((c) => mentions(c.text).has(r.id)).map((c) => c.id));
    for (const m of named) for (const id of byMsg.get(m) ?? []) ids.add(id);
    return [r.id, [...ids]];
  }));
  const cell = (s) => s.replace(/\|/g, '\\|');
  const lines = [
    `# Coverage: ${row.feature}`,
    '<!-- Generated by kb.mjs coverage. Do not edit: run it again after the cases or the atlas change. -->',
    `Atlas pages: ${row.atlas.join(', ') || 'none'} · Cases files: ${row.cases.join(', ') || 'none'} · Cases: ${cases.length}`,
    '',
    'A message counts as covered when a case checks its exact text or cites its ID. A rule counts as covered',
    'when a case cites its ID or covers a message the rule names. This is a guide, not proof.',
    '',
    '## Messages',
    '| Atlas | Exact text | Covered by |',
    '|---|---|---|',
    ...messages.map((m) => `| ${m.id} | ${cell(m.text)} | ${byMsg.get(m.id).join(', ') || '**not covered**'} |`),
    '',
    '## Rules',
    '| Atlas | Rule | Covered by |',
    '|---|---|---|',
    ...rules.map((r) => `| ${r.id} | ${cell(r.text)} | ${byRule.get(r.id).join(', ') || '**not covered**'} |`),
    '',
    '## Gaps',
  ];
  const gaps = [...messages.filter((m) => !byMsg.get(m.id).length).map((m) => m.id), ...rules.filter((r) => !byRule.get(r.id).length).map((r) => r.id)];
  lines.push(gaps.length ? `Not covered: ${gaps.join(', ')}.` : 'None found.');
  if (messages.length + rules.length) lines.push('', `Covered: ${messages.length + rules.length - gaps.length} of ${messages.length + rules.length} atlas facts.`);
  return lines.join('\n') + '\n';
}

// ---- stamp, search, load --------------------------------------------------------------

// Adds @hash to atlas references in decisions.md that have none. Never changes an existing hash.
export function stamp(text, ctx) {
  let added = 0;
  const out = text.split('\n').map((line) => line.replace(SRC, (whole, inner) => {
    const parts = inner.split(';').map((p) => {
      const t = p.trim();
      const r = parseRefs(`[src: ${t}]`)[0];
      if (!r || r.bad || r.kind !== 'atlas' || !r.anchor || r.hash) return t;
      const got = resolveRef(r, ctx);
      if (got.problem) return t;
      added++;
      return `${t} @${factHash(got.text)}`;
    });
    return `[src: ${parts.join('; ')}]`;
  }));
  return { text: out.join('\n'), added };
}

export function search(words, ctx) {
  const terms = words.map((w) => w.toLowerCase()).filter(Boolean);
  const hits = [];
  if (!terms.length || !existsSync(ctx.root)) return hits;
  const walk = (dir) => {
    for (const f of readdirSync(dir).sort()) {
      const p = join(dir, f);
      if (statSync(p).isDirectory()) walk(p);
      else if (f.endsWith('.md')) {
        read(p).split('\n').forEach((line, i) => {
          const l = line.toLowerCase();
          if (terms.every((t) => l.includes(t))) {
            const rel = relative(ctx.root, p);
            hits.push({ feature: rel.includes(sep) || rel.includes('/') ? rel.split(/[\\/]/)[0] : '(index)', file: relative(ctx.project, p), line: i + 1, text: line.trim(), sources: parseRefs(line).map((r) => r.raw) });
          }
        });
      }
    }
  };
  walk(ctx.root);
  return hits;
}

export function loadFeature(folder, ctx, { all = false } = {}) {
  if (!isSlug(folder)) throw new Error(`"${folder}" is not a feature folder name`);
  const dir = join(ctx.root, folder);
  const files = all ? [...FEATURE_FILES, 'coverage.md'] : DEFAULT_LOAD;
  const parts = files.map((f) => join(dir, f)).filter(existsSync).map((p) => `<!-- ${relative(ctx.project, p)} -->\n${read(p)}`);
  const text = parts.join('\n');
  return { text, tokens: tokens(text), over: tokens(text) > ctx.cap * (all ? 3 : 1) };
}

// ---- inventory and scripted writes (kb build, kb answer, draft-bug) ----------------------------

const mdFiles = (dir) => existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith('.md')).sort() : [];

// What exists in the project that a feature map can be built from.
export function inventory(ctx) {
  const firstHeading = (t) => (t.match(/^#\s+(.*)$/m) ?? [])[1]?.trim() ?? '';
  const atlas = mdFiles(ctx.atlasDir).map((f) => {
    const t = read(join(ctx.atlasDir, f));
    return { page: f.slice(0, -3), title: firstHeading(t), screens: [...t.matchAll(/^###\s+(.*)$/gm)].map((m) => m[1].trim()),
      messages: (t.match(/^\|\s*M\d+\s*\|/gm) ?? []).length, rules: (t.match(/^\s*[-*]\s*R\d+\s/gm) ?? []).length };
  });
  const cases = existsSync(ctx.casesDir) ? readdirSync(ctx.casesDir).filter((f) => /\.(md|csv)$/.test(f)).sort().map((f) => {
    const t = read(join(ctx.casesDir, f));
    const head = t.split('\n').slice(0, 4).join(' ');
    return { file: f, title: firstHeading(t), ticket: (head.match(/Ticket:\s*([^\s·]+)/) ?? [])[1] ?? null, atlas: (head.match(/Atlas:\s*([^\s·]+)/) ?? [])[1] ?? null };
  }) : [];
  const bugsDir = join(ctx.project, ctx.bugs ?? 'qa/bugs');
  const bugs = mdFiles(bugsDir).map((f) => {
    const t = read(join(bugsDir, f));
    return { file: relative(ctx.project, join(bugsDir, f)).split(sep).join('/'), title: firstHeading(t), atlas: (t.match(/\*\*Atlas:\*\*\s*(\S+)/) ?? [])[1] ?? null, filed: /^\s*(Filed|Issue):\s*https?:/mi.test(t) };
  });
  const ticketsDir = join(ctx.project, 'tickets');
  const tickets = mdFiles(ticketsDir).map((f) => `tickets/${f}`);
  for (const c of cases) if (c.ticket && !tickets.includes(c.ticket) && existsSync(join(ctx.project, c.ticket))) tickets.push(c.ticket);
  const sources = existsSync(ctx.sourcesDir) ? readdirSync(ctx.sourcesDir).sort() : [];
  const index = join(ctx.root, 'index.md');
  const features = existsSync(index) ? parseIndex(read(index)).rows.map(({ feature, folder, atlas: a, cases: c, tickets: t }) => ({ feature, folder, atlas: a, cases: c, tickets: t })) : [];
  return { features, atlas, cases, tickets, bugs, sources };
}

// ---- similar features (for tickets whose screen is not built yet) ---------------------------------

const STOP = new Set('the a an and or of to in on for with is are be as by at it this that from your you user users when then should can will not no yes new page screen app button field fields shows show must able want so as'.split(' '));
const wordsOf = (t) => new Set(String(t).toLowerCase().replace(/[«»‹›"“”`*_#|()[\]{}:;,.!?/\\-]/g, ' ').split(/\s+/).filter((w) => w.length > 2 && !STOP.has(w) && !/^\d+$/.test(w)));

// Field labels of an atlas page (first column of field tables).
export function atlasFields(text) {
  const out = new Set();
  for (const line of observedAtlas(text).split('\n')) {
    const m = line.match(/^\|\s*([^|]+?)\s*\|\s*[^|]*\|\s*(yes|no|not tested|[^|]*)\s*\|/i);
    if (m && !/^(Field|#|-+|:?-+:?|M\d+|R\d+|G\d+|\d+)$/i.test(m[1]) && m[1].length < 40) out.add(m[1]);
  }
  return [...out];
}

// Ranks atlas pages by how much they share with the ticket: field labels named in the ticket count
// most, then shared words. Returns [{ page, score, fields: [shared field labels], words: [...] }].
export function similar(ticketText, ctx, { exclude = [], top = 3 } = {}) {
  const tw = wordsOf(ticketText);
  const lower = String(ticketText).toLowerCase();
  const out = [];
  for (const f of mdFiles(ctx.atlasDir)) {
    const page = f.slice(0, -3);
    if (exclude.includes(page)) continue;
    const text = read(join(ctx.atlasDir, f));
    const fields = atlasFields(text).filter((x) => new RegExp(`(^|[^a-z])${esc(x.toLowerCase())}([^a-z]|$)`).test(lower));
    const aw = wordsOf(observedAtlas(text));
    const shared = [...tw].filter((w) => aw.has(w));
    const score = Math.round((fields.length * 3 + shared.length / Math.max(4, Math.sqrt(tw.size))) * 100) / 100;
    if (fields.length || shared.length >= 3) out.push({ page, score, fields, words: shared.slice(0, 12) });
  }
  return out.sort((a, b) => b.score - a.score).slice(0, top);
}

// Which features cover these atlas pages (or mention these words in their name or folder).
export function featuresFor(ctx, { pages = [], words: ws = [] } = {}) {
  const index = join(ctx.root, 'index.md');
  if (!existsSync(index)) return [];
  const want = pages.map((p) => p.replace(/^.*[\\/]/, '').replace(/\.md$/, ''));
  return parseIndex(read(index)).rows.filter((r) => r.atlas.some((a) => want.includes(a))
    || ws.some((w) => `${r.feature} ${r.folder}`.toLowerCase().includes(w.toLowerCase())));
}

const nextId = (text, letter) => `${letter}${Math.max(0, ...[...text.matchAll(new RegExp(`^##\\s+${letter}(\\d+)\\b`, 'gm'))].map((m) => Number(m[1]))) + 1}`;
const oneLine = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

// Appends a decision. Returns { id, entry } or { problem }. Never edits existing decisions.
export function addDecision(ctx, folder, { title, question, decision, who, date, src }) {
  if (!isSlug(folder)) return { problem: `"${folder}" is not a feature folder name (lowercase words with dashes)` };
  const file = join(ctx.root, folder, 'decisions.md');
  if (!existsSync(file)) return { problem: `no feature folder ${folder} (decisions.md not found)` };
  for (const [k, v] of Object.entries({ title, question, decision, who, src })) if (!oneLine(v)) return { problem: `${k} is empty` };
  if (!DATE.test(date ?? '')) return { problem: 'date must look like 2026-11-26' };
  if (/«[^»]+»|"[^"]{2,}"|“[^”]{2,}”/.test(decision)) return { problem: 'a decision settles intent, not UI text: say what the team wants without quoting screen text (exact text comes only from the atlas)' };
  const refs = parseRefs(`[src: ${src}]`);
  for (const r of refs) if (r.kind === 'atlas' && !r.anchor) return { problem: `${r.raw}: cite the atlas fact by its ID (#M12, #R6) or screen heading so a later change can be noticed` };
  for (const r of refs) { const got = resolveRef(r, ctx); if (got.problem) return { problem: got.problem }; }
  if (sensitiveLine([title, question, decision, who].join(' '), ctx.testDomain)) return { problem: 'the decision contains a secret or a real email address; name people by role' };
  const text = read(file);
  const id = nextId(text, 'D');
  let entry = `## ${id} ${oneLine(title)}\n- Question: ${oneLine(question)} [src: ${oneLine(src)}]\n- Decision: ${oneLine(decision)}\n- Who: ${oneLine(who)}\n- Date: ${date}\n- Status: active\n`;
  entry = stamp(entry, ctx).text;
  return { id, entry, file, text: text.replace(/\n*$/, '\n\n') + entry };
}

export function addIssue(ctx, folder, { title, status = 'open', bug, link, seen, screens }) {
  if (!isSlug(folder)) return { problem: `"${folder}" is not a feature folder name (lowercase words with dashes)` };
  const file = join(ctx.root, folder, 'known-issues.md');
  if (!existsSync(file)) return { problem: `no feature folder ${folder} (known-issues.md not found)` };
  if (!oneLine(title)) return { problem: 'title is empty' };
  if (!['open', 'fixed', 'wont-fix'].includes(status)) return { problem: 'status must be open, fixed or wont-fix' };
  if (!bug && !link) return { problem: 'give the bug file (--bug) or a tracker link (--link)' };
  if (bug) { const got = resolveRef({ raw: `bug:${bug}`, kind: 'bug', path: bug, anchor: null }, ctx); if (got.problem) return { problem: got.problem }; }
  if (link && !/^https?:\/\/\S+$/.test(link)) return { problem: 'link must be a web address' };
  const text = read(file);
  if (bug && text.includes(`[src: bug:${bug}]`)) return { problem: `${bug} is already listed in known-issues.md` };
  const id = nextId(text, 'K');
  const entry = [`## ${id} ${oneLine(title)}`, `- Status: ${status}`, bug ? `- Bug: [src: bug:${bug}]` : null, link ? `- Link: ${link}` : null,
    screens ? `- Screens: ${oneLine(screens)}` : null, `- Seen: ${seen ?? new Date().toISOString().slice(0, 10)}`].filter(Boolean).join('\n') + '\n';
  return { id, entry, file, text: text.replace(/\n*$/, '\n\n') + entry };
}

// "decision <folder>/D1" and "known issue <folder>/K1" cited in cases or bugs: must exist; a cited
// decision must still be active.
export function checkKbCitations(text, ctx) {
  const problems = [];
  text.split('\n').forEach((line, i) => {
    for (const m of line.matchAll(/\b(decision|known issue)\s+([a-z0-9]+(?:-[a-z0-9]+)*)\/([DK]\d+)\b/gi)) {
      const [, kind, folder, id] = m;
      const isDec = kind.toLowerCase() === 'decision';
      if ((isDec && id[0] !== 'D') || (!isDec && id[0] !== 'K')) { problems.push({ line: i + 1, message: `${m[0]}: decisions are D<n>, known issues K<n>` }); continue; }
      const file = join(ctx.root, folder, isDec ? 'decisions.md' : 'known-issues.md');
      if (!existsSync(file)) { problems.push({ line: i + 1, message: `${m[0]}: no feature "${folder}" in the knowledge base` }); continue; }
      const e = entries(read(file)).find((x) => x.id === id);
      if (!e) { problems.push({ line: i + 1, message: `${m[0]} does not exist` }); continue; }
      if (isDec) {
        const status = (e.fields.status?.value ?? 'active').toLowerCase();
        if (status !== 'active') problems.push({ line: i + 1, message: `${m[0]} is ${status}: ask the team again instead of relying on it` });
        else {
          for (const r of e.lines.flatMap((l) => parseRefs(l.text)).filter((r) => r.kind === 'atlas' && r.hash)) {
            const got = resolveRef(r, ctx);
            if (!got.problem && factHash(got.text) !== r.hash) problems.push({ line: i + 1, message: `${m[0]} is stale: the atlas fact it relies on changed. Ask the team again` });
          }
        }
      }
    }
  });
  return problems;
}

// ---- pre-UI cases: ‹expected: text [src: …]› ------------------------------------------------
// Expected screen text written before the screen exists. The source must be a ticket, a manual or
// an imported file (a decision settles intent, never UI text). Only reconcile.mjs turns these into
// «…» after the text is found in the atlas.
// similar: text borrowed from a similar, already built feature's atlas page (marked as borrowed).
export const PRE_UI_KINDS = ['ticket', 'manual', 'import', 'similar'];
const EXPECTED = /‹expected:\s*([^‹›]*?)\s*\[src:\s*([^\]]*)\]\s*›|‹expected:\s*([^‹›]*?)\s*›/g;

export function expectations(text) {
  const out = [];
  text.split('\n').forEach((line, i) => {
    for (const m of line.matchAll(EXPECTED)) {
      const raw = m[0];
      const body = (m[1] ?? m[3] ?? '').trim();
      out.push({ line: i + 1, raw, text: body.replace(/^"(.*)"$/, '$1').replace(/^“(.*)”$/, '$1'), src: m[2] ?? null });
    }
  });
  return out;
}

export const isPreUi = (text) => /\bAtlas:\s*none yet\b/i.test(text.split('\n').slice(0, 6).join('\n'));

export function checkPreUi(text, ctx) {
  const problems = [];
  const exp = expectations(text);
  const pre = isPreUi(text);
  for (const e of exp) {
    const add = (m) => problems.push({ line: e.line, message: `${e.raw.length > 70 ? e.raw.slice(0, 67) + '…›' : e.raw}: ${m}` });
    if (!e.text) { add('the expected text is empty'); continue; }
    if (!e.src) { add('needs a source: ‹expected: text [src: ticket:<path>#AC<n>]›'); continue; }
    const refs = parseRefs(`[src: ${e.src}]`);
    const texts = [];
    for (const r of refs) {
      if (r.bad) { add(`"${r.raw}" is not a source reference`); continue; }
      if (!PRE_UI_KINDS.includes(r.kind)) { add(`expected screen text can only come from ${PRE_UI_KINDS.join(', ')} (not ${r.kind}); decisions settle intent, the atlas settles real text`); continue; }
      const got = resolveRef(r, ctx);
      if (got.problem) add(got.problem); else texts.push(norm(got.text));
    }
    if (texts.length && !texts.some((t) => t.includes(norm(e.text)))) add(`"${e.text}" is not word for word in the cited source`);
  }
  // Unclosed or malformed markup.
  text.split('\n').forEach((line, i) => {
    const open = (line.match(/‹/g) ?? []).length, close = (line.match(/›/g) ?? []).length;
    if (open !== close) problems.push({ line: i + 1, message: 'unbalanced ‹ › on this line' });
  });
  if (pre) {
    const body = text.split(/^#{1,6}\s*Mismatches\b.*$/im)[0];
    body.split('\n').forEach((line, i) => {
      if (/«[^»\n]+»/.test(line)) problems.push({ line: i + 1, message: 'a pre-UI cases file (Atlas: none yet) may not mark text with «»: there is no screen to copy it from. Use ‹expected: text [src: …]›; reconcile converts it once the screen exists' });
    });
  }
  return { expectations: exp.length, preUi: pre, problems };
}
